function GeminiReportSection({report,error,loading,onRetry}:{report?:GeminiReport;error?:string;loading:boolean;onRetry:()=>void}){
 if(loading)return <section className="medical-report-section"><div className="section-number">03</div><div className="medical-section-body"><h3>Generating structured report…</h3><p className="section-intro">The transcript is de-identified locally before the Gemini request. Patient details are restored locally after generation.</p></div></section>;
 if(error)return <section className="medical-report-section"><div className="section-number">03</div><div className="medical-section-body"><h3>Report generation failed</h3><p className="section-intro">{error}</p><button className="secondary" onClick={onRetry}><Activity size={14}/> Retry report</button></div></section>;
 if(!report)return <section className="medical-report-section"><div className="section-number">03</div><div className="medical-section-body"><h3>AI-assisted clinical report</h3><p className="section-intro">Generate a structured report from the saved transcript.</p><button className="secondary" onClick={onRetry}>Generate report</button></div></section>;
 const doc=report.report;
 const groups:Array<[string,GeminiFinding[]]>=[['Maternal findings',doc.maternal_findings],['Child findings',doc.child_findings],['Patient findings',doc.patient_findings],['Caregiver details',doc.caregiver_findings],['Medicines reported',doc.medicines],['Symptoms and observations',doc.symptoms_and_observations],['Counseling and actions recorded',doc.counseling_and_actions]];
 return <section className="medical-report-section"><div className="section-number">03</div><div className="medical-section-body"><h3>{doc.title||'Gemini-generated clinical documentation'}</h3><p className="section-intro">Generated from a locally de-identified transcript. Profile details were restored on this device. Review all findings before sharing.</p><div className="report-fact-list"><h4>Patient summary</h4><p>{doc.patient_summary||doc.encounter_summary||'No summary was generated.'}</p></div>{(doc.chief_complaints||[]).length>0&&<div className="report-fact-list"><h4>Chief complaints</h4><ul>{(doc.chief_complaints||[]).map((item,i)=><li key={i}>{item}</li>)}</ul></div>}{(doc.vitals_table||[]).length>0&&<div className="report-fact-list"><h4>Vitals recorded</h4><table className="report-vitals"><thead><tr><th>Parameter</th><th>Recorded value</th><th>Reference</th><th>Status</th></tr></thead><tbody>{(doc.vitals_table||[]).map((v,i)=><tr key={i}><td>{v.parameter}</td><td>{v.value}</td><td>{v.reference}</td><td>{v.status}</td></tr>)}</tbody></table></div>}{(doc.observations||[]).length>0&&<div className="report-fact-list"><h4>Observations</h4><ul>{(doc.observations||[]).map((item,i)=><li key={i}>{item}</li>)}</ul></div>}{(doc.assessment||[]).length>0&&<div className="report-fact-list"><h4>AI-suggested · for clinician review</h4><ul>{(doc.assessment||[]).map((item,i)=><li key={i}>{item}</li>)}</ul></div>}{(doc.plan||[]).length>0&&<div className="report-fact-list"><h4>Documented plan</h4><ul>{(doc.plan||[]).map((item,i)=><li key={i}>{item}</li>)}</ul></div>}{doc.simple_summary_local&&<div className="report-fact-list"><h4>Patient-friendly summary</h4><p>{doc.simple_summary_local}</p></div>}<div className="report-fact-list"><h4>Encounter summary</h4><p>{doc.encounter_summary||'No summary was generated.'}</p></div>{(doc.risk_flags||[]).length>0&&<div className="report-fact-list risk-flags"><h4>Deterministic documentation flags · review promptly</h4><ul>{(doc.risk_flags||[]).map(flag=><li key={flag.code}><b>{flag.severity.toUpperCase()}</b> · {flag.message} — {flag.recommended_action}</li>)}</ul></div>}{(doc.missing_information||[]).length>0&&<div className="report-fact-list"><h4>Information not reported</h4><ul>{(doc.missing_information||[]).map(item=><li key={item}>{item}</li>)}</ul></div>}{groups.map(([title,items])=>items?.length>0&&<div className="report-fact-list" key={title}><h4>{title}</h4><ul>{items.map((item,index)=><li key={`${item.field}-${index}`}><b>{item.field}</b>: {item.value}{item.unit?` ${item.unit}`:''}{item.needs_verification&&<em> · Verify</em>}{item.source_quote&&<small className="gemini-source">Source: {item.source_quote}</small>}</li>)}</ul></div>)}{doc.other_details?.length>0&&<div className="report-fact-list"><h4>Other details reported</h4><ul>{doc.other_details.map((item,index)=><li key={index}>{item}</li>)}</ul></div>}{doc.follow_up?.length>0&&<div className="report-fact-list"><h4>Follow-up discussed</h4><ul>{doc.follow_up.map((item,index)=><li key={index}>{item}</li>)}</ul></div>}{doc.items_to_verify?.length>0&&<div className="report-fact-list"><h4>Items to verify</h4><ul>{doc.items_to_verify.map((item,index)=><li key={index}>{item}</li>)}</ul></div>}</div></section>;
}
function ReportVoiceControls({visitId,report,language,online,onChange}:{visitId:string;report:GeminiReport;language:string;online:boolean;onChange:(report:GeminiReport)=>void}){
 const [state,setState]=useState('Ready');const [error,setError]=useState('');const [transcript,setTranscript]=useState('');const [diff,setDiff]=useState('');const [clarification,setClarification]=useState('');const [voiceConfirmation,setVoiceConfirmation]=useState('');const [busy,setBusy]=useState(false);const recorder=useRef<MediaRecorder|null>(null);const chunks=useRef<Blob[]>([]);const stream=useRef<MediaStream|null>(null);const player=useRef<HTMLAudioElement|null>(null);const playbackContext=useRef<AudioContext|null>(null);const playbackSource=useRef<AudioBufferSourceNode|null>(null);const lastAudio=useRef<Blob|null>(null);const playbackToken=useRef(0);const readRequest=useRef(false);const playbackBuffer=useRef<AudioBuffer|null>(null);const playbackScope=useRef<'full'|'changes'|null>(null);const playbackOffset=useRef(0);const playbackStartedAt=useRef(0);const holdActive=useRef(false);const timer=useRef<ReturnType<typeof setTimeout>|null>(null);
 const wav=async(blob:Blob)=>{const ctx=new AudioContext();try{const decoded=await ctx.decodeAudioData(await blob.arrayBuffer());const length=Math.ceil(decoded.duration*16000);const out=new OfflineAudioContext(1,length,16000);const source=out.createBufferSource();source.buffer=decoded;source.connect(out.destination);source.start();const mono=await out.startRendering();const pcm=mono.getChannelData(0);const buffer=new ArrayBuffer(44+pcm.length*2);const view=new DataView(buffer);const str=(offset:number,value:string)=>[...value].forEach((c,i)=>view.setUint8(offset+i,c.charCodeAt(0)));str(0,'RIFF');view.setUint32(4,36+pcm.length*2,true);str(8,'WAVE');str(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,16000,true);view.setUint32(28,32000,true);view.setUint16(32,2,true);view.setUint16(34,16,true);str(36,'data');view.setUint32(40,pcm.length*2,true);for(let i=0;i<pcm.length;i++)view.setInt16(44+i*2,Math.max(-1,Math.min(1,pcm[i]))*32767,true);return new Blob([buffer],{type:'audio/wav'})}finally{await ctx.close()}};
 const stopReading=()=>{playbackToken.current++;const source=playbackSource.current;const context=playbackContext.current;if(source&&context&&playbackBuffer.current){playbackOffset.current=Math.min(playbackBuffer.current.duration,playbackOffset.current+Math.max(0,context.currentTime-playbackStartedAt.current))}playbackSource.current=null;if(source){source.onended=null;try{source.stop()}catch{}}playbackContext.current=null;if(context)void context.close();readRequest.current=false;setBusy(false);setState(playbackBuffer.current&&playbackOffset.current<playbackBuffer.current.duration?'Paused':'Ready')};
 const read=async(scope:'full'|'changes'='full')=>{if(playbackSource.current||state==='Speaking'){stopReading();return}if(!online){setError('Voice read-back is unavailable offline. You can review and edit the report manually.');return}if(busy||readRequest.current)return;readRequest.current=true;const token=++playbackToken.current;setBusy(true);setError('');setState(playbackBuffer.current&&playbackScope.current===scope?'Resuming report':'Preparing read-back');let context:AudioContext|undefined;try{context=new AudioContext();playbackContext.current=context;await context.resume();let audio:AudioBuffer;if(playbackBuffer.current&&playbackScope.current===scope&&playbackOffset.current<playbackBuffer.current.duration){audio=playbackBuffer.current}else{playbackBuffer.current=null;playbackScope.current=scope;playbackOffset.current=0;const response=await fetch(`/api/reports/${encodeURIComponent(visitId)}/speak`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope,language})});if(!response.ok){const payload=await response.json();throw Error(payload.error||'Read-back failed.')}const bytes=await response.arrayBuffer();if(!bytes.byteLength)throw Error('Gnani returned empty audio. Retry.');audio=await context.decodeAudioData(bytes);playbackBuffer.current=audio;playbackScope.current=scope}if(token!==playbackToken.current)return;const source=context.createBufferSource();playbackSource.current=source;source.buffer=audio;source.connect(context.destination);source.onended=()=>{if(token!==playbackToken.current)return;playbackSource.current=null;readRequest.current=false;playbackBuffer.current=null;playbackOffset.current=0;playbackScope.current=null;setState('Ready');void context?.close();if(playbackContext.current===context)playbackContext.current=null};setState('Speaking');playbackStartedAt.current=context.currentTime;source.start(0,playbackOffset.current)}catch(e){if(token!==playbackToken.current)return;playbackSource.current=null;readRequest.current=false;setState('Ready');await context?.close();if(playbackContext.current===context)playbackContext.current=null;setError(e instanceof Error?e.message:'Read-back failed. Retry.')}finally{if(token===playbackToken.current)setBusy(false)}};
 const start=async(requireHold=true)=>{if(!online){setError('Voice correction is unavailable offline. You can edit the report manually.');return}try{setError('');setTranscript('');setDiff('');setClarification('');setVoiceConfirmation('');setState('Preparing microphone');stream.current=await navigator.mediaDevices.getUserMedia({audio:true});if(requireHold&&!holdActive.current){stream.current.getTracks().forEach(t=>t.stop());stream.current=null;setState('Ready');return}const mime=MediaRecorder.isTypeSupported('audio/mp4')?'audio/mp4':MediaRecorder.isTypeSupported('audio/webm')?'audio/webm':'';const rec=new MediaRecorder(stream.current,mime?{mimeType:mime}:undefined);recorder.current=rec;chunks.current=[];rec.ondataavailable=e=>{if(e.data.size)chunks.current.push(e.data)};rec.onstop=()=>{stream.current?.getTracks().forEach(t=>t.stop());stream.current=null;void submit(new Blob(chunks.current,{type:rec.mimeType||'audio/mp4'}))};rec.start();setState('Listening · speak a correction');timer.current=setTimeout(()=>{if(rec.state==='recording')rec.stop()},30000)}catch{setState('Ready');setError('Microphone access was denied or unavailable. You can edit the report manually.')}};
 const stop=()=>{holdActive.current=false;if(timer.current)clearTimeout(timer.current);if(recorder.current?.state==='recording'){setState('Understanding correction');recorder.current.stop()}};
 const submit=async(blob:Blob)=>{if(busy)return;lastAudio.current=blob;setBusy(true);setState('Preparing audio');try{const audio=await wav(blob);const form=new FormData();form.append('audio_file',audio,'correction.wav');setState('Understanding correction');const response=await fetch(`/api/reports/${encodeURIComponent(visitId)}/correct?language=${encodeURIComponent(language+',en-IN')}`,{method:'POST',body:form});const payload=await response.json();if(!response.ok)throw Error(payload.error||'Correction failed. Retry.');lastAudio.current=null;setTranscript(payload.transcript||'');setClarification(payload.clarifyingQuestion||'');setVoiceConfirmation(payload.spokenConfirmation||'');if(payload.patch&&Object.keys(payload.patch).length){onChange(payload.report);const operations=payload.patch.operations||[];const changes=operations.map((op:{action:string;target:string;section:string;value?:string})=>op.action==='remove'?`Removed “${op.target}” from ${op.section.replaceAll('_',' ')}`:`Changed “${op.target}” to “${op.value}”`);if(payload.patch.encounter_summary)changes.push('Updated the encounter summary');if(payload.patch.title)changes.push('Updated the report title');setDiff(changes.join('. ')||'Report updated.');setState('Updated · review and confirm the change');}else setState(payload.clarifyingQuestion?'Clarification needed':'No changes applied');}catch(e){setState('Ready');setError(e instanceof Error?e.message:'Correction failed. Retry.')}finally{setBusy(false)}};
 const undo=async()=>{setBusy(true);setError('');try{const r=await fetch(`/api/reports/${encodeURIComponent(visitId)}/undo`,{method:'POST'});const p=await r.json();if(!r.ok)throw Error(p.error);onChange(p);setDiff('Last report change undone.');setState('Previous version restored')}catch(e){setError(e instanceof Error?e.message:'Undo failed.')}finally{setBusy(false)}};
 const confirm=async()=>{setBusy(true);try{const r=await fetch(`/api/reports/${encodeURIComponent(visitId)}/confirm`,{method:'POST'});const p=await r.json();if(!r.ok)throw Error(p.error);onChange(p.report||{...report,status:'confirmed'});setState('Confirmed')}catch(e){setError(e instanceof Error?e.message:'Could not confirm report.')}finally{setBusy(false)}};
 useEffect(()=>()=>{if(timer.current)clearTimeout(timer.current);player.current?.pause();if(playbackSource.current){playbackSource.current.onended=null;try{playbackSource.current.stop()}catch{}}void playbackContext.current?.close();stream.current?.getTracks().forEach(t=>t.stop())},[]);
 return <div className="report-voice-controls no-print"><h3>Review this report</h3><p className="section-intro">Read the report aloud, request corrections by voice, then confirm after review. Voice features require an internet connection.</p><div className="report-actions"><button className={state==='Speaking'?'primary':'secondary'} disabled={(busy&&state!=='Speaking')||(!online&&state!=='Speaking')} aria-label={state==='Speaking'?'Stop reading report':state==='Paused'?'Resume report':'Read report aloud'} onClick={()=>void read('full')}>{state==='Speaking'?<Square size={14}/>:<Play size={14}/>} {state==='Speaking'?'Stop reading':state==='Paused'?'Resume report':'Read report'}</button><button className="secondary" disabled={busy||!online||state.startsWith('Speaking')} onPointerDown={e=>{e.currentTarget.setPointerCapture(e.pointerId);holdActive.current=true;void start()}} onPointerUp={stop} onPointerCancel={stop} onKeyDown={e=>{if(e.key===' '&&!e.repeat){e.preventDefault();holdActive.current=true;void start()}}} onKeyUp={e=>{if(e.key===' '){e.preventDefault();stop()}}}>{state.startsWith('Listening')?<Square size={14}/>:<Mic size={14}/>} {state.startsWith('Listening')?'Release to finish':'Hold to correct'}</button><button className="secondary" disabled={busy||state==='Speaking'||!online||!report.version||report.version<2} onClick={()=>void read('changes')}><Play size={14}/> Read changes</button><button className="secondary" disabled={busy||!online||!report.version||report.version<2} onClick={()=>void undo()}>Undo</button><button className="primary" disabled={busy||report.status==='confirmed'} onClick={()=>void confirm()}><Check size={14}/> {report.status==='confirmed'?'Confirmed':'Confirm report'}</button></div><p aria-live="polite">{state}</p>{transcript&&<div className="report-fact-list"><h4>I heard</h4><p>{transcript}</p></div>}{voiceConfirmation&&<div className="report-fact-list"><h4>Confirmation</h4><p>{voiceConfirmation}</p></div>}{diff&&<div className="report-fact-list"><h4>Report updated</h4><p>{diff}</p></div>}{clarification&&<div className="report-fact-list"><h4>Please clarify</h4><p>{clarification}</p><button className="secondary" onClick={()=>void start(false)}>Record clarification</button></div>}{error&&<div className="report-fact-list"><p role="alert">{error}</p><button className="secondary" onClick={()=>lastAudio.current?void submit(lastAudio.current):void read('full')}>Retry</button></div>}</div>;
}
